db-percentiles.solution:
def percentile_report(latencies, ps):
    if not latencies:
        return []
    xs = sorted(latencies)
    n = len(xs)
    out = []
    for p in ps:
        rank = -(-p * n // 100)          # ceil(p*n/100) using integer maths
        out.append(xs[max(rank, 1) - 1])
    return out

