db-fencing-token.solution:
class FencedStore:
    def __init__(self):
        self.issued = 0
        self.max_seen = 0
        self.data = {}
        self.owner = None

    def acquire(self, client):
        self.issued += 1
        self.owner = client
        return self.issued

    def write(self, token, key, value):
        if token < 1 or token > self.issued or token < self.max_seen:
            return False
        self.max_seen = token
        self.data[key] = value
        return True

    def read(self, key):
        return self.data.get(key)

    def holder(self):
        return self.owner
